CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC, anon;
GRANT USAGE ON SCHEMA private TO authenticated, service_role;
ALTER FUNCTION public.claim_mission(uuid) SET SCHEMA private;
ALTER FUNCTION public.create_tournament(text,text) SET SCHEMA private;
ALTER FUNCTION public.get_my_missions() SET SCHEMA private;
ALTER FUNCTION public.join_room(uuid) SET SCHEMA private;
ALTER FUNCTION public.join_tournament(uuid) SET SCHEMA private;
ALTER FUNCTION public.purchase_frame(uuid) SET SCHEMA private;
ALTER FUNCTION public.start_mission(uuid) SET SCHEMA private;
ALTER FUNCTION public.record_verified_game_event(uuid,text,integer,text) SET SCHEMA private;
REVOKE ALL ON FUNCTION private.claim_mission(uuid),private.create_tournament(text,text),private.get_my_missions(),private.join_room(uuid),private.join_tournament(uuid),private.purchase_frame(uuid),private.start_mission(uuid) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION private.record_verified_game_event(uuid,text,integer,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION private.claim_mission(uuid),private.create_tournament(text,text),private.get_my_missions(),private.join_room(uuid),private.join_tournament(uuid),private.purchase_frame(uuid),private.start_mission(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION private.record_verified_game_event(uuid,text,integer,text) TO service_role;
CREATE OR REPLACE FUNCTION public.claim_mission(p_user_mission_id uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path TO '' AS $$ SELECT private.claim_mission(p_user_mission_id); $$;
CREATE OR REPLACE FUNCTION public.create_tournament(p_game text,p_platform text) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path TO '' AS $$ SELECT private.create_tournament(p_game,p_platform); $$;
CREATE OR REPLACE FUNCTION public.get_my_missions() RETURNS TABLE(user_mission_id uuid,mission_id uuid,slug text,title text,description text,category text,difficulty text,target integer,progress integer,reward_xp integer,reward_pf integer,started_at timestamptz,completed_at timestamptz,claimed_at timestamptz,period_key text) LANGUAGE sql SECURITY INVOKER SET search_path TO '' AS $$ SELECT * FROM private.get_my_missions(); $$;
CREATE OR REPLACE FUNCTION public.join_room(p_room_id uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path TO '' AS $$ SELECT private.join_room(p_room_id); $$;
CREATE OR REPLACE FUNCTION public.join_tournament(p_tournament_id uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path TO '' AS $$ SELECT private.join_tournament(p_tournament_id); $$;
CREATE OR REPLACE FUNCTION public.purchase_frame(p_frame_id uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path TO '' AS $$ SELECT private.purchase_frame(p_frame_id); $$;
CREATE OR REPLACE FUNCTION public.start_mission(p_mission_id uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path TO '' AS $$ SELECT private.start_mission(p_mission_id); $$;
CREATE OR REPLACE FUNCTION public.record_verified_game_event(p_user_id uuid,p_event_type text,p_amount integer,p_external_event_id text) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path TO '' AS $$ SELECT private.record_verified_game_event(p_user_id,p_event_type,p_amount,p_external_event_id); $$;
REVOKE ALL ON FUNCTION public.claim_mission(uuid),public.create_tournament(text,text),public.get_my_missions(),public.join_room(uuid),public.join_tournament(uuid),public.purchase_frame(uuid),public.start_mission(uuid) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.record_verified_game_event(uuid,text,integer,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_mission(uuid),public.create_tournament(text,text),public.get_my_missions(),public.join_room(uuid),public.join_tournament(uuid),public.purchase_frame(uuid),public.start_mission(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.record_verified_game_event(uuid,text,integer,text) TO service_role;
DROP FUNCTION public.get_room_counts();
DROP FUNCTION public.get_tournament_counts();
CREATE TABLE public.room_public_counts(room_id uuid PRIMARY KEY,member_count integer NOT NULL DEFAULT 0 CHECK(member_count>=0),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.tournament_public_counts(tournament_id uuid PRIMARY KEY,registration_count integer NOT NULL DEFAULT 0 CHECK(registration_count>=0),updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.room_public_counts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tournament_public_counts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public read room aggregate counts" ON public.room_public_counts FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "public read tournament aggregate counts" ON public.tournament_public_counts FOR SELECT TO anon,authenticated USING(true);
GRANT SELECT ON public.room_public_counts,public.tournament_public_counts TO anon,authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.room_public_counts,public.tournament_public_counts FROM anon,authenticated;
GRANT ALL ON public.room_public_counts,public.tournament_public_counts TO service_role;
INSERT INTO public.room_public_counts(room_id,member_count) SELECT r.id,count(rm.user_id)::integer FROM public.rooms r LEFT JOIN public.room_members rm ON rm.room_id=r.id GROUP BY r.id ON CONFLICT(room_id) DO UPDATE SET member_count=excluded.member_count,updated_at=now();
INSERT INTO public.tournament_public_counts(tournament_id,registration_count) SELECT t.id,count(tr.id)::integer FROM public.tournaments t LEFT JOIN public.tournament_registrations tr ON tr.tournament_id=t.id GROUP BY t.id ON CONFLICT(tournament_id) DO UPDATE SET registration_count=excluded.registration_count,updated_at=now();
CREATE OR REPLACE FUNCTION private.sync_room_public_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$ DECLARE v_id uuid; BEGIN v_id:=CASE WHEN TG_OP='DELETE' THEN OLD.room_id ELSE NEW.room_id END; INSERT INTO public.room_public_counts(room_id,member_count,updated_at) SELECT v_id,count(*)::integer,now() FROM public.room_members WHERE room_id=v_id ON CONFLICT(room_id) DO UPDATE SET member_count=excluded.member_count,updated_at=now(); RETURN NULL; END; $$;
CREATE OR REPLACE FUNCTION private.sync_tournament_public_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$ DECLARE v_id uuid; BEGIN v_id:=CASE WHEN TG_OP='DELETE' THEN OLD.tournament_id ELSE NEW.tournament_id END; INSERT INTO public.tournament_public_counts(tournament_id,registration_count,updated_at) SELECT v_id,count(*)::integer,now() FROM public.tournament_registrations WHERE tournament_id=v_id ON CONFLICT(tournament_id) DO UPDATE SET registration_count=excluded.registration_count,updated_at=now(); RETURN NULL; END; $$;
CREATE TRIGGER sync_room_count_after_membership AFTER INSERT OR DELETE ON public.room_members FOR EACH ROW EXECUTE FUNCTION private.sync_room_public_count();
CREATE TRIGGER sync_tournament_count_after_registration AFTER INSERT OR DELETE ON public.tournament_registrations FOR EACH ROW EXECUTE FUNCTION private.sync_tournament_public_count();